v></section></div><div class="section-head"><div><h2>Spotlight cards</h2><p>A few favorites from across the worlds.</p></div><button class="text-btn" data-view="collection">View collection ↗</button></div><div class="card-row">${['dandy','vaggie','blitzo','loona','stolas'].map(id=>cardMarkup(getCard(id))).join('')}</div>`}

