function fighterMarkup(c,hp,max){return `<div class="fighter"><div class="card-art" style="--accent:${c.color}"><span class="card-glyph">${c.glyph}</span></div><h3>${c.name}</h3><small>${c.type} · Weak to ${c.weakness}</small><div class="hp-wrap"><div class="hp-label"><span>❤ HP</span><span>${Math.max(0,hp)} / ${max}</span></div><div class="hp-track"><span style="width:${Math.max(0,hp)/max*100}%"></span></div></div></div>`}
function startBattle(){const available=CHARACTERS.filter(c=>ownedCount(c.id)>0);const hero=getCard(available[Math.floor(Math.random()*available.length)]?.id||'dandy'),foes=CHARACTERS.filter(c=>c.id!==hero.id),foe=getCard(foes[Math.floor(Math.random()*foes.length)].id);const tools=UTILITY.filter(c=>ownedCount(c.id)>0).map(c=>c.id);battle={player:{id:hero.id,hp:hero.hp,maxHp:hero.hp},enemy:{id:foe.id,hp:foe.hp,maxHp:foe.hp},hand:tools.sort(()=>Math.random()-.5).slice(0,3),turn:1,mode:selectedMode,over:false,won:false,boost:0,log:`${hero.name} faces ${foe.name}! Pick an action to begin.`};navigate('battle')}
function endBattle(won){battle.over=true;battle.won=won;state.matches++;if(won){state.wins++;state.gold+=50;battle.log='Victory! Your reward: 50 gold. The crowd goes wild!';toast('Victory! +50 gold ✦')}else{battle.log='Your fighter is down. Every loss teaches a new trick!'}save()}
function takeTurn(){if(!battle||battle.over)return;const enemy=getCard(battle.enemy.id),hero=getCard(battle.player.id);let damage=enemy.attack+(Math.floor(Math.random()*7)-3);if(hero.weakness===enemy.type)damage=Math.round(damage*1.35);battle.player.hp=Math.max(0,battle.player.hp-damage);battle.turn++;if(battle.player.hp<=0){endBattle(false);return}battle.log=`${enemy.name} used ${enemy.attackName}! ${damage} damage. Your turn.`;render()}
function playerAttack(){if(!battle||battle.over)return;const hero=getCard(battle.player.id),enemy=getCard(battle.enemy.id);let damage=hero.attack+battle.boost;battle.boost=0;if(enemy.weakness===hero.type)damage=Math.round(damage*1.4);battle.enemy.hp=Math.max(0,battle.enemy.hp-damage);if(battle.enemy.hp<=0){endBattle(true);render();return}battle.log=`${hero.name} used ${hero.attackName} for ${damage} damage!`;takeTurn()}
function playUtility(id){if(!battle||battle.over)return;const card=getCard(id);if(!card)return;let msg='';switch(id){case'life':battle.player.hp=Math.min(battle.player.maxHp,battle.player.hp+25);msg='Restored 25 HP!';break;case'wish':msg='A wish for good fortune! (Your next turn is empowered.)';battle.boost+=5;break;case'blessing':battle.boost+=10;msg='Blessed! Your next attack deals +10.';break;case'curse':battle.enemy.hp=Math.max(0,battle.enemy.hp-10);msg='Jinxed! The rival loses 10 HP.';break;case'gamble':if(Math.random()>.45){battle.boost+=20;msg='Lucky roll! +20 attack damage.'}else{battle.player.hp=Math.max(0,battle.player.hp-10);msg='Bad luck! The gamble costs you 10 HP.'}break;case'revive':if(battle.player.hp<=0)battle.player.hp=30;else battle.player.hp=Math.min(battle.player.maxHp,battle.player.hp+15);msg='Second chance! Restored 15 HP.';break}battle.hand=battle.hand.filter(x=>x!==id);if(battle.enemy.hp<=0){battle.log=`${card.name}: ${msg}`;endBattle(true);render();return}if(battle.player.hp<=0){battle.log=`${card.name}: ${msg}`;endBattle(false);render();return}battle.log=`${card.name}: ${msg}`;takeTurn()}
function openPack(id){const packs={starter:{name:'Chaos Awakens',price:90,number:4,cardsPer:5,promos:1},deluxe:{name:'Worlds Collide',price:160,number:8,cardsPer:7,promos:2},jumbo:{name:'Jumbo Celebration Box',price:280,number:15,cardsPer:10,promos:3}}[id];if(!packs)return;if(state.gold<packs.price){toast('Not enough gold — win battles for more!');return}state.gold-=packs.price;let pulls=[];const randomCard=()=>{let pool=ALL_CARDS.filter(c=>c.kind==='character'||ownedCount(c.id)>0);return pool[Math.floor(Math.random()*pool.length)]};for(let i=0;i<packs.number*packs.cardsPer;i++){let c=randomCard();state.inventory[c.id]=(state.inventory[c.id]||0)+1;pulls.push(c)}const promoCount=Math.min(5,packs.promos+Math.floor(Math.random()*2));for(let i=0;i<promoCount;i++){let c=getCard(CHARACTERS[Math.floor(Math.random()*CHARACTERS.length)].id+'-evo');state.inventory[c.id]=(state.inventory[c.id]||0)+1;pulls.unshift(c)}save();const shown=pulls.slice(0,5);document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><span class="eyebrow">BOX OPENED</span><h2>${packs.name}</h2></div><button class="close-btn" data-close>×</button></div><p class="modal-copy">You opened ${packs.number} packs and found ${pulls.length} cards, including ${promoCount} evolution promos! Showing a few highlights below.</p><div class="reveal-cards">${shown.map(c=>cardMarkup(c,true)).join('')}</div><div class="modal-actions"><button class="primary" data-close>Sweet! · +${pulls.length} cards</button></div></div></div>`;render()}
function evolveCard(id){let base=getCard(id),evo=getCard(id+'-evo');if(!base||!evo)return;if(state.gold<50||ownedCount(id)<2){toast('Need 2 copies of this character and 50 gold to evolve.');return}state.gold-=50;state.inventory[id]--;state.inventory[evo.id]=(state.inventory[evo.id]||0)+1;save();toast(`${base.name} evolved into ${evo.name}!`);render()}
function addDeck(){if(state.decks.length>=8){toast('You can save up to 8 decks.');return}const name=prompt('Name your new deck:','New deck');if(name===null)return;const d={id:'deck-'+Date.now(),name:name.trim()||'New deck',cards:{}};state.decks.push(d);selectedDeckId=d.id;save();render()}
function renameDeck(id){const d=state.decks.find(x=>x.id===id);if(!d)return;const name=prompt('Rename deck:',d.name);if(name?.trim()){d.name=name.trim();save();render()}}
function bindViewEvents(){const root=document.getElementById('main-content');root.onclick=e=>{const target=e.target.closest('button,[data-view],[data-select-deck]');if(!target)return;if(target.dataset.view){navigate(target.dataset.view);return}if(target.dataset.action==='start-battle'){startBattle();return}if(target.dataset.action==='attack'){playerAttack();return}if(target.dataset.action==='new-deck'){addDeck();return}if(target.dataset.action==='set-active'){state.activeDeck=selectedDeckId;save();toast('Active deck updated.');render();return}if(target.dataset.action==='rename-current'){renameDeck(selectedDeckId);return}if(target.dataset.format){selectedFormat=target.dataset.format;root.querySelectorAll('.format-chip').forEach(x=>x.classList.toggle('active',x.dataset.format===selectedFormat));const s=root.querySelector('#format-select');if(s)s.value=selectedFormat;return}if(target.dataset.mode){selectedMode=target.dataset.mode;render();return}if(target.dataset.filter){collectionFilter=target.dataset.filter;render();return}if(target.dataset.buy){openPack(target.dataset.buy);return}if(target.dataset.playCard){playUtility(target.dataset.playCard);return}if(target.dataset.evolve){evolveCard(target.dataset.evolve);return}if(target.dataset.selectDeck){selectedDeckId=target.dataset.selectDeck;render();return}if(target.dataset.deckCard){changeDeckCard(target.dataset.deckCard,Number(target.dataset.delta));return}if(target.dataset.rename){renameDeck(target.dataset.rename);return}};root.oninput=e=>{if(e.target.id==='card-search'){searchTerm=e.target.value;const pos=e.target.selectionStart;render();const i=root.querySelector('#card-search');i.focus();i.setSelectionRange(pos,pos)}};root.onchange=e=>{if(e.target.id==='format-select')selectedFormat=e.target.value;if(e.target.id==='mode-select'){selectedMode=e.target.value;render()}if(e.target.id==='deck-select'){state.activeDeck=e.target.value;selectedDeckId=e.target.value;save();render()}}}
function changeDeckCard(id,delta){let d=state.decks.find(x=>x.id===selectedDeckId);if(!d)return;let total=Object.values(d.cards).reduce((a,b)=>a+b,0),current=d.cards[id]||0;if(delta>0){if(total>=150){toast('Deck reached its 150-card limit.');return}if(current>=ownedCount(id)){toast('No more copies available in your collection.');return}d.cards[id]=current+1}else{if(current<1)return;if(current===1)delete d.cards[id];else d.cards[id]=current-1}save();render()}
let selectedFormat='Standard';
document.addEventListener('click',e=>{const t=e.target.closest('[data-view]');if(t&&!document.getElementById('main-content').contains(t)){navigate(t.dataset.view);return}if(e.target.closest('[data-close]')||e.target.classList.contains('modal-backdrop')){document.getElementById('modal-root').innerHTML=''}});
document.querySelectorAll('.nav-item,.mobile-nav button,.brand').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
document.getElementById('modal-root').addEventListener('click',e=>{if(e.target.closest('[data-close]')||e.target.classList.contains('modal-backdrop'))e.currentTarget.innerHTML=''});
document.getElementById('sound-toggle').addEventListener('click',e=>{e.currentTarget.classList.toggle('muted');toast(e.currentTarget.classList.contains('muted')?'Sound off':'Sound on')});
render();

